import numpy as np
import pandas as pd
import pickle
import tempfile
import unittest
from io import BytesIO

from history_matching.basis import Basis
from history_matching.error import HistoryMatchingError

class BasisTest(unittest.TestCase):

    def test_identity(self):
        data = pd.DataFrame({'x':[1,2,3],'y':[4,5,6],'z':[7,8,9]})
        b = Basis.make_identity_basis(params=data.keys())
        self.assertTrue((b.generate_dmatrix(data)==data).all().all())
        self.assertRaises(HistoryMatchingError, b.generate_dmatrix, data, scaleX=True) #Didn't provide param_info

    def test_none_value(self):
        data = pd.DataFrame({'x':[1,2,3],'y':[4,None,6],'z':[7,8,9]})
        b = Basis.make_identity_basis(params=data.keys())
        self.assertRaises(HistoryMatchingError, b.generate_dmatrix, data, scaleX=True) #Didn't provide param_info

    def test_nan_value(self):
        data = pd.DataFrame({'x':[1,2,3],'y':[4,np.nan,6],'z':[7,8,9]})
        b = Basis.make_identity_basis(params=data.keys())
        self.assertRaises(HistoryMatchingError, b.generate_dmatrix, data, scaleX=True) #Didn't provide param_info

    def test_polynomial_intercept(self):
        data = pd.DataFrame({'x':[1,2,3],'y':[4,5,6],'z':[7,8,9]})
        b = Basis.make_polynomial_basis(params=data.keys(), intercept=True, order=0)
        intercept_frame = pd.DataFrame({'1': [1,1,1]})
        self.assertRaises(HistoryMatchingError, b.generate_dmatrix, data, scaleX=True) #Didn't provide param_info
        self.assertTrue((b.generate_dmatrix(data)==intercept_frame).all().all())

    def test_polynomial_first(self):
        data = pd.DataFrame({'x':[1,2,3],'y':[4,5,6],'z':[7,8,9]})
        b = Basis.make_polynomial_basis(params=data.keys(), intercept=True, order=1)
        intercept_frame = pd.DataFrame({'1': [1,1,1]})
        self.assertRaises(HistoryMatchingError, b.generate_dmatrix, data, scaleX=True) #Didn't provide param_info
        self.assertTrue((b.generate_dmatrix(data)==pd.concat([intercept_frame, data], axis=1)).all().all())

    def test_polynomial_second(self):
        data = pd.DataFrame({'x':[1,2,3],'y':[4,5,6],'z':[7,8,9]})
        b = Basis.make_polynomial_basis(params=data.keys(), intercept=True, order=2)
        ans = pd.DataFrame({'1': {0: 1.0, 1: 1.0, 2: 1.0}, 'x': {0: 1.0, 1: 2.0, 2: 3.0}, 'y': {0: 4.0, 1: 5.0, 2: 6.0}, 'z': {0: 7.0, 1: 8.0, 2: 9.0}, 'x^2': {0: 1.0, 1: 4.0, 2: 9.0}, 'y^2': {0: 16.0, 1: 25.0, 2: 36.0}, 'z^2': {0: 49.0, 1: 64.0, 2: 81.0}, 'x y': {0: 4.0, 1: 10.0, 2: 18.0}, 'x z': {0: 7.0, 1: 16.0, 2: 27.0}, 'y z': {0: 28.0, 1: 40.0, 2: 54.0}})
        ans = ans.reindex(sorted(ans.columns), axis=1)
        self.assertRaises(HistoryMatchingError, b.generate_dmatrix, data, scaleX=True) #Didn't provide param_info
        self.assertTrue((b.generate_dmatrix(data)==ans).all().all())

    def test_polynomial_third(self):
        data = pd.DataFrame({'x':[1,2,3],'y':[4,5,6],'z':[7,8,9]})
