    def test_pickle(self):
        data = pd.DataFrame({'x':[1,2,3],'y':[4,5,6],'z':[7,8,9]})
        basis = Basis.make_polynomial_basis(params=data.keys(), intercept=True, order=5)

        outfile = BytesIO()
        pickle.dump(basis, outfile)
        outfile.seek(0)
        basis_loaded = pickle.load(outfile)

        for x in basis.__dict__:
            self.assertEqual(basis.__dict__[x], basis_loaded.__dict__[x])

